import json, sys


def solve(r):
    txs = r.get('transactions') or []
    initial = dict(r.get('initial') or {})
    final = dict(r.get('final') or {})
    n = len(txs)
    if n == 0:
        return {"order": [] if initial == final else None}

    # Compile operations and collect the key universe.
    keyset = set(initial) | set(final)
    compiled = []
    # Per transaction: key -> set of values it may leave on that key.
    wvals = []
    for t in txs:
        cops = []
        wv = {}
        for op in t['ops']:
            kind = op[0]
            if kind == 'get':
                keyset.add(op[1])
                cops.append((0, op[1], op[2]))
            elif kind == 'put':
                keyset.add(op[1])
                wv.setdefault(op[1], set()).add(op[2])
                cops.append((1, op[1], op[2]))
            elif kind == 'del':
                keyset.add(op[1])
                wv.setdefault(op[1], set()).add(None)
                cops.append((2, op[1]))
            elif kind == 'cas':
                keyset.add(op[1])
                # The new value applies only when the comparison succeeds.
                wv.setdefault(op[1], set()).add(op[3])
                cops.append((3, op[1], op[2], op[3], op[4]))
            elif kind == 'scan':
                cops.append((4, op[1], op[2], op[3]))
            else:
                raise ValueError('unknown op ' + str(kind))
        compiled.append(cops)
        wvals.append(wv)

    keys = sorted(keyset)
    kidx = {k: i for i, k in enumerate(keys)}
    nk = len(keys)
    final_gets = [final.get(k) for k in keys]
    # wsets[i][ki] = frozenset of values tx i may leave on key ki (None = absent).
    wsets = [[frozenset(wv.get(k, ())) for k in keys] for wv in wvals]
    writes_key = [[bool(wsets[i][ki]) for ki in range(nk)] for i in range(n)]

    # Realtime precedence: j must precede i iff txs[j].end <= txs[i].start.
    pred = [0] * n
    for i in range(n):
        pi = 0
        si = txs[i]['start']
        for j in range(n):
            if j != i and txs[j]['end'] <= si:
                pi |= 1 << j
        pred[i] = pi

    def apply(d, cops):
        d = dict(d)
        for op in cops:
            k = op[0]
            if k == 1:            # put
                d[op[1]] = op[2]
            elif k == 0:          # get
                if d.get(op[1]) != op[2]:
                    return None
            elif k == 2:          # del
                if op[1] in d:
                    del d[op[1]]
            elif k == 3:          # cas
                cur = d.get(op[1])
                ok = (cur == op[2])
                if ok != op[4]:
                    return None
                if ok:
                    if op[3] is None:
                        d.pop(op[1], None)
                    else:
                        d[op[1]] = op[3]
            else:                 # scan
                low, high, exp = op[1], op[2], op[3]
                pairs = [[kk, d[kk]] for kk in sorted(d) if low <= kk < high]
                if pairs != exp:
                    return None
        return d

    full = (1 << n) - 1
    failed = set()

    def dfs(mask, d, order):
        if mask == full:
            return list(order) if d == final else None
        key = (mask, tuple(sorted(d.items())))
        if key in failed:
            return None
        # Value-reachability prune: for every key, the final value must be
        # either its current value (if nobody left writes it) or a value some
        # remaining transaction may leave on it.
        rem = ~mask
        for ki in range(nk):
            fv = final_gets[ki]
            cur = d.get(keys[ki])
            if cur == fv:
                continue
            reach = False
            for i in range(n):
                if (rem >> i) & 1 and fv in wsets[i][ki]:
                    reach = True
                    break
            if not reach:
                failed.add(key)
                return None
        for i in range(n):
            bit = 1 << i
            if mask & bit:
                continue
            if pred[i] & rem:
                continue
            nd = apply(d, compiled[i])
            if nd is None:
                continue
            order.append(i)
            res = dfs(mask | bit, nd, order)
            if res is not None:
                return res
            order.pop()
        failed.add(key)
        return None

    res = dfs(0, initial, [])
    if res is None:
        return {"order": None}
    ids = [t['id'] for t in txs]
    return {"order": [ids[i] for i in res]}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.append(json.dumps(solve(json.loads(line))))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


if __name__ == '__main__':
    main()
